export async function retry<T>(
  fn: () => Promise<T>,
  options: {
    maxAttempts: number
    baseDelayMs: number
    shouldRetry: (error: unknown) => boolean
  }
): Promise<T> {
  let attempt = 0
  while (true) {
    attempt++
    try {
      return await fn()
    } catch (error) {
      if (attempt >= options.maxAttempts) throw error
      if (!options.shouldRetry(error)) throw error
      const backoff = options.baseDelayMs * 2 ** (attempt - 1)
      const jitter = Math.random() * options.baseDelayMs
      await new Promise<void>((resolve) =>
        setTimeout(resolve, backoff + jitter)
      )
    }
  }
}

